def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # Find a full-width or full-height separator of a non-background color.
    sep = None
    for r, row in enumerate(grid):
        if row[0] != background and all(v == row[0] for v in row):
            sep = ("h", r, row[0])
            break
    if sep is None:
        for c in range(w):
            color = grid[0][c]
            if color != background and all(grid[r][c] == color for r in range(h)):
                sep = ("v", c, color)
                break
    if sep is None:
        return [row[:] for row in grid]

    axis, index, sep_color = sep
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] not in (background, sep_color)]
    if not points:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    if axis == "h":
        minr, maxr = min(r for r, c in points), max(r for r, c in points)
        if maxr < index:
            delta = index - 1 - maxr
            trail = minr - 1
        else:
            delta = index + 1 - minr
            trail = maxr + (index + 1 - minr) + 1
        for r, c in points:
            out[r][c] = background
        for r, c in points:
            nr = r + delta
            if 0 <= nr < h:
                out[nr][c] = grid[r][c]
        if 0 <= trail < h:
            out[trail] = [8] * w
    else:
        minc, maxc = min(c for r, c in points), max(c for r, c in points)
        if maxc < index:
            delta = index - 1 - maxc
            trail = minc - 1
        else:
            delta = index + 1 - minc
            trail = maxc + (index + 1 - minc) + 1
        for r, c in points:
            out[r][c] = background
        for r, c in points:
            nc = c + delta
            if 0 <= nc < w:
                out[r][nc] = grid[r][c]
        if 0 <= trail < w:
            for r in range(h):
                out[r][trail] = 8
    return out
